const input = Array.isArray($json) ? $json : [$json];
return input.map((engagement) => {
  const happy = `${engagement.outcomeSatisfaction ?? ''}`.toLowerCase() === 'happy' || engagement.clientWouldRefer === true;
  const optOut = engagement.reviewOptOut === true;
  const eligible = happy && !optOut;
  return { json: { ...engagement, reviewAction: eligible ? 'send-review-request' : 'manager-follow-up-first', reviewLink: eligible ? engagement.reviewLink ?? 'https://g.page/r/firm-review-placeholder' : null, complianceNote: 'No compensation offered for reviews. Bar rules vary by state — verify per firm.' } };
});
